export const dynamic = 'force-static';

export default async function Dashboard() {
  // A personal endpoint fetched WITHOUT cache control. Under the
  // App Router's default data cache this result can be cached and
  // served to the wrong user or shown long after a profile edit.
  const res = await fetch('https://api.example.com/me');
  const me = await res.json();

  return (
    <main>
      <h1>Welcome, {me.name}</h1>
      <p>Plan: {me.plan}</p>
    </main>
  );
}

import { cookies } from 'next/headers';
import { cache } from 'react';

// A personalized page must be dynamic: read cookies to prove it.
const getSession = cache(async () => cookies().get('session')?.value);

const getMe = cache(async (token: string) => {
  const res = await fetch('https://api.example.com/me', {
    headers: { authorization: `Bearer ${token}` },
    next: { revalidate: 60 } // data cache: max 60s, tag-able
  });
  return res.json();
});

export default async function Dashboard() {
  const token = await getSession();
  if (!token) return <p>Sign in</p>;

  const me = await getMe(token);
  return (
    <main>
      <h1>Welcome, {me.name}</h1>
      <p>Plan: {me.plan}</p>
    </main>
  );
}

